<template><section class="business" v-loading="loading">
  <h1>{{attendance?'考勤管理':'表扬管理'}}</h1><p class="hint">{{attendance?'按发生日期记录迟到、早退和缺勤。同一天可有不同合法记录；同类记录需核对后确认。':'记录学生每一次值得肯定的表现，同一学生可以拥有多条表扬。'}}记录人由当前登录账号自动生成。</p>
  <div class="filters"><el-select v-model="filters.classId" clearable placeholder="全部班级" aria-label="记录班级"><el-option v-for="c in classes" :key="c.id" :value="c.id" :label="c.className+' · '+c.academicYear"/></el-select><StudentPicker v-model="filters.studentId" :class-id="filters.classId"/><el-date-picker v-model="filters.from" type="date" value-format="YYYY-MM-DD" placeholder="开始日期" aria-label="记录开始日期"/><el-date-picker v-model="filters.to" type="date" value-format="YYYY-MM-DD" placeholder="结束日期" aria-label="记录结束日期"/><el-select v-if="attendance" v-model="filters.type" clearable placeholder="全部类型" aria-label="考勤类型筛选"><el-option v-for="(label,key) in types" :key="key" :value="key" :label="label"/></el-select><el-button :loading="loading" @click="search">查询</el-button><el-button v-if="isAdmin" type="primary" @click="open()">{{attendance?'新增考勤':'新增表扬'}}</el-button></div>
  <div class="record-metrics"><template v-if="attendance"><MetricCard v-for="(label,key) in types" :key="key" :label="label+'次数'" :value="stats.reduce((sum,row)=>sum+Number(row[key]||0),0)" detail="当前学生、班级与日期范围，含所有类型"/></template><template v-else><MetricCard label="表扬次数" :value="stats.reduce((sum,row)=>sum+Number(row.count||0),0)" detail="当前学生、班级与日期范围"/><MetricCard label="获表扬学生" :value="stats.length" detail="统计范围内去重学生数"/></template></div>
  <MobileList v-if="narrow" :items="rows" :primary="r=>r.studentName" :secondary="r=>r.studentNo"
    :badge="r=>attendance?r.type:(r.reason||'')" empty="暂无匹配记录"
    :fields="[{k:'className',label:'班级'},{k:'occurredDate',label:'日期',format:r=>attendance?r.occurredDate:r.praiseDate},{k:'occurredTime',label:'时间',format:r=>attendance?(r.occurredTime||''):''},{k:'reason',label:'表扬原因',format:r=>attendance?'':(r.reason||'')},{k:'recorder',label:'记录人'},{k:'remark',label:'备注'}]">
    <template #actions="{row}"><el-button link @click="detail=row;detailDialog=true">详情</el-button><template v-if="isAdmin"><el-button link @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template>
  </MobileList>
  <el-table v-else :data="rows" empty-text="暂无匹配记录"><el-table-column prop="studentNo" label="学号" min-width="110"/><el-table-column prop="studentName" label="学生" min-width="90"/><el-table-column prop="className" label="班级" min-width="130"/><el-table-column :prop="attendance?'occurredDate':'praiseDate'" label="日期" width="120"/><el-table-column v-if="attendance" label="类型" width="80"><template #default="{row}"><StatusTag :status="row.type" kind="attendance"/></template></el-table-column><el-table-column v-if="attendance" prop="occurredTime" label="时间" width="100"/><el-table-column v-else prop="reason" label="表扬原因" min-width="200"/><el-table-column prop="recorder" label="记录人" min-width="100"/><el-table-column prop="remark" label="备注" min-width="150"/><el-table-column fixed="right" label="操作" :width="isAdmin?190:80"><template #default="{row}"><el-button link @click="detail=row;detailDialog=true">详情</el-button><template v-if="isAdmin"><el-button link @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></template></el-table-column></el-table>
  <el-pagination v-model:current-page="page" :total="total" :page-size="10" :pager-count="5" layout="total,prev,pager,next" @current-change="load"/>
  <h2 class="subheading">{{attendance?'考勤次数统计':'获得表扬的学生与次数'}}</h2><p class="hint">统计当前学生、班级与日期范围；考勤统计同时列出三种类型。班级按学生当前所属班级筛选。</p><el-table :data="stats" empty-text="该范围暂无统计数据"><el-table-column prop="studentNo" label="学号" min-width="110"/><el-table-column prop="studentName" label="学生" min-width="100"/><template v-if="attendance"><el-table-column v-for="(label,key) in types" :key="key" :prop="key" :label="label+'次数'" min-width="100"/></template><el-table-column v-else prop="count" label="表扬次数" min-width="110"/></el-table>
  <el-dialog v-model="dialog" :title="(form.id?'编辑':'新增')+(attendance?'考勤':'表扬')" width="min(540px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="学生（必选）"><StudentPicker v-model="form.studentId"/></el-form-item><el-form-item :label="attendance?'发生日期（必填）':'表扬日期（必填）'"><el-date-picker v-model="form[attendance?'occurredDate':'praiseDate']" type="date" value-format="YYYY-MM-DD"/></el-form-item><template v-if="attendance"><el-form-item label="考勤类型（必选）"><el-select v-model="form.type"><el-option v-for="(label,key) in types" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item label="发生时间（可空）"><el-time-picker v-model="form.occurredTime" value-format="HH:mm:ss"/></el-form-item></template><el-form-item v-else label="表扬原因（必填，最多500字）"><el-input v-model="form.reason" type="textarea" maxlength="500" show-word-limit/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="detailDialog" title="记录详情" width="min(560px,94vw)"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="学生">{{detail.studentName}} · {{detail.studentNo}}</el-descriptions-item><el-descriptions-item label="日期">{{detail.occurredDate||detail.praiseDate}}</el-descriptions-item><el-descriptions-item :label="attendance?'考勤':'表扬原因'">{{attendance?types[detail.type]:detail.reason}}</el-descriptions-item><el-descriptions-item label="发生时间" v-if="attendance">{{detail.occurredTime||'未填写'}}</el-descriptions-item><el-descriptions-item label="备注">{{detail.remark||'无'}}</el-descriptions-item><el-descriptions-item label="记录人">{{detail.recorder}}</el-descriptions-item><el-descriptions-item label="创建时间">{{detail.createdAt}}</el-descriptions-item><el-descriptions-item label="更新时间">{{detail.updatedAt}}</el-descriptions-item></el-descriptions></el-dialog>
</section></template>
<script setup>
import MobileList from '../components/MobileList.vue';
import {useNarrow} from '../composables/useNarrow';
const narrow=useNarrow();

import MetricCard from '../components/MetricCard.vue';
import StatusTag from '../components/StatusTag.vue';
import {ref,reactive,computed,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import api from '../api';import StudentPicker from '../components/StudentPicker.vue';import './business.css';
const props=defineProps({classes:Array,isAdmin:Boolean,kind:String});const attendance=computed(()=>props.kind==='attendance'),base=computed(()=>attendance.value?'/attendance':'/praises');
const types={LATE:'迟到',EARLY_LEAVE:'早退',ABSENT:'缺勤'},filters=reactive({classId:null,studentId:null,from:null,to:null,type:null}),rows=ref([]),stats=ref([]),page=ref(1),total=ref(0),loading=ref(false),saving=ref(false),dialog=ref(false),detailDialog=ref(false),form=reactive({}),detail=ref();
let loadSequence=0;
const error=e=>ElMessage.error(e.response?.data?.message||e.message||'请求失败');
function params(){return Object.fromEntries(Object.entries(filters).filter(([k,v])=>v!==null&&v!==''&&v!==undefined&&(attendance.value||k!=='type')))}
async function load(){const request=++loadSequence;loading.value=true;try{const p=params();const [r,s]=await Promise.all([api.get(base.value,{params:{...p,page:page.value-1}}),api.get(base.value+'/statistics',{params:p})]);if(request!==loadSequence)return;rows.value=r.data.data.content;total.value=r.data.data.total;stats.value=s.data.data}catch(e){error(e)}finally{if(request===loadSequence)loading.value=false}}
function search(){if(filters.from&&filters.to&&filters.from>filters.to)return ElMessage.warning('开始日期不能晚于结束日期');page.value=1;load()}
function open(row){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{id:null,studentId:filters.studentId,occurredDate:null,praiseDate:null,occurredTime:null,type:'LATE',reason:'',remark:''},row||{});dialog.value=true}
async function save(){if(saving.value)return;if(!form.studentId||!(attendance.value?form.occurredDate:form.praiseDate)||(!attendance.value&&!form.reason?.trim()))return ElMessage.warning('请选择学生、日期并填写必填内容');saving.value=true;try{let confirmed=false;if(attendance.value){const matches=(await api.post('/attendance/duplicates',form,{params:{id:form.id||undefined}})).data.data;if(matches.length){await ElMessageBox.confirm(`该学生当日已有 ${matches.length} 条同类记录：${matches.map(r=>(r.occurredTime||'时间未填')+' '+(r.remark||'无备注')).join('；')}。是否仍确认保存？`,'疑似重复考勤',{type:'warning',confirmButtonText:'仍然保存',cancelButtonText:'取消'});confirmed=true}}await api({url:form.id?`${base.value}/${form.id}`:base.value,method:form.id?'put':'post',data:{...form,confirmDuplicate:confirmed}});dialog.value=false;await load();ElMessage.success('记录已保存')}catch(e){if(e!=='cancel'&&e!=='close')error(e)}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确定删除 ${row.studentName} 的这条${attendance.value?'考勤':'表扬'}记录并移入回收站？之后可恢复。`,'移入回收站',{type:'warning',confirmButtonText:'移入回收站',cancelButtonText:'取消'});await api.delete(`${base.value}/${row.id}`);if(rows.value.length===1&&page.value>1)page.value--;await load();ElMessage.success('记录已移入回收站')}catch(e){if(e!=='cancel'&&e!=='close')error(e)}}
onMounted(load);
</script>
